def build(n):
    # Deterministic Hamiltonian-cycle-plus-perfect-matching cubic construction.
    if n < 4:
        return [list(range(v)) + list(range(v + 1, n)) for v in range(n)]
    if n & 1:
        return [[u for u in range(n) if u != v] for v in range(n)]

    def make_graph(matching):
        g = [[] for _ in range(n)]
        for v in range(n):
            w = (v + 1) % n
            g[v].append(w)
            g[w].append(v)
        for a, b in matching:
            g[a].append(b)
            g[b].append(a)
        for row in g:
            row.sort()
        return g

    def cycle_count(g, length):
        if length > n:
            return 0
        total = 0
        for start in range(n):
            used = 1 << start

            def dfs(v, depth, first):
                if depth == length:
                    return int(start in g[v] and first < v)
                count = 0
                for w in g[v]:
                    if w <= start or (used >> w) & 1:
                        continue
                    nonlocal_used[0] = used | (1 << w)
                    count += walk(w, depth + 1, first, nonlocal_used[0])
                return count

            def walk(v, depth, first, mask):
                if depth == length:
                    return int(start in g[v] and first < v)
                count = 0
                for w in g[v]:
                    if w <= start or (mask >> w) & 1:
                        continue
                    count += walk(w, depth + 1, first, mask | (1 << w))
                return count

            nonlocal_used = [used]
            for first in g[start]:
                if first > start:
                    total += walk(first, 2, first, used | (1 << first))
        return total

    state = (0x9E3779B9 ^ (n * 0x85EBCA6B)) & 0xffffffff

    def rnd():
        nonlocal state
        state ^= (state << 13) & 0xffffffff
        state ^= state >> 17
        state ^= (state << 5) & 0xffffffff
        state &= 0xffffffff
        return state

    shortlist = []
    attempts = 5000

    for _ in range(attempts):
        p = list(range(n))
        for i in range(n - 1, 0, -1):
            j = rnd() % (i + 1)
            p[i], p[j] = p[j], p[i]

        matching = []
        valid = True
        for i in range(0, n, 2):
            a, b = p[i], p[i + 1]
            if (a - b) % n in (1, n - 1):
                valid = False
                break
            matching.append((a, b))
        if not valid:
            continue

        g = make_graph(matching)
        preliminary = cycle_count(g, 4) + cycle_count(g, 8)
        key = (preliminary, matching)

        if len(shortlist) < 64:
            shortlist.append(key)
            shortlist.sort(key=lambda x: x[0])
        elif preliminary < shortlist[-1][0]:
            shortlist[-1] = key
            shortlist.sort(key=lambda x: x[0])

    if not shortlist:
        matching = [(v, (v + n // 2) % n) for v in range(n // 2)]
        return make_graph(matching)

    best_graph = None
    best_score = None

    for _, matching in shortlist:
        g = make_graph(matching)
        score = cycle_count(g, 4) + cycle_count(g, 8)
        if n >= 16:
            score += cycle_count(g, 16)
        if n >= 32:
            score += cycle_count(g, 32)
        signature = tuple(tuple(row) for row in g)
        candidate = (score, signature)
        if best_score is None or candidate < best_score:
            best_score = candidate
            best_graph = g

    return best_graph
